import asyncio,json,pathlib
from playwright.async_api import async_playwright
O=pathlib.Path('watch-bevel-output');build=json.loads((O/'build.json').read_text());C=pathlib.Path(build['releasePath']);C=C.relative_to(pathlib.Path.cwd()) if C.is_absolute() else C
# Extract only the previously verified diagnostic target helper, not its test runner.
s=pathlib.Path('watch-bevel-ci/contextual-qa.py').read_text();hook=s.split("HOOK=r'''",1)[1].split("'''",1)[0]
review=(C/'assembly-review.js').read_text().replace('composer.render();','composer.render();window.__mobileQAFrames=(window.__mobileQAFrames||0)+1;')+'\n'+hook+"\nwindow.__contextQA.pause=()=>{$('animate-movement').checked=false;$('animate').checked=false;setClockPlayback();dirty=true};window.__contextQA.redraw=()=>{dirty=true};"
(C/'qa-review.js').write_text(review);(C/'qa-atelier.js').write_text((C/'atelier-preview.js').read_text().replace('./assembly-review.js?v=atelier-local-1','./qa-review.js'));(C/'qa-atelier.html').write_text((C/'atelier-preview.html').read_text().replace('atelier-preview.js','qa-atelier.js'))
async def main():
 report={'errors':[],'console':[],'states':[],'scope':'Fresh SwiftShader mobile browser, actual sealed app plus separate frame-count/target hook; no app changes.'}
 async with async_playwright() as p:
  browser=await p.chromium.launch(headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);context=await browser.new_context(viewport={'width':430,'height':850},device_scale_factor=1,is_mobile=True,has_touch=True);page=await context.new_page();page.set_default_timeout(60000);page.on('pageerror',lambda e:report['errors'].append(str(e)));page.on('console',lambda e:report['console'].append({'type':e.type,'text':e.text}));await page.add_init_script("window.__contextEvents=[];document.addEventListener('webglcontextlost',()=>__contextEvents.push({event:'lost',time:performance.now()}),true);document.addEventListener('webglcontextrestored',()=>__contextEvents.push({event:'restored',time:performance.now()}),true)")
  async def save(label):
   await page.wait_for_timeout(2000);frames=await page.evaluate('window.__mobileQAFrames||0');await page.evaluate('__contextQA.redraw()');await page.wait_for_function('(f)=>(window.__mobileQAFrames||0)>f',arg=frames,timeout=60000)
   state=await page.evaluate("({frames:window.__mobileQAFrames,events:window.__contextEvents,canvas:{width:document.querySelector('#assembly-canvas').width,height:document.querySelector('#assembly-canvas').height,bounds:document.querySelector('#assembly-canvas').getBoundingClientRect().toJSON()},stage:document.querySelector('#stage').getBoundingClientRect().toJSON(),snapshot:__contextQA.snapshot(),presentation:assemblyInspect().presentation})");report['states'].append({'label':label,**state});print(label,json.dumps(state),flush=True);(O/'mobile-qa-report.json').write_text(json.dumps(report,indent=2));await page.screenshot(path=str(O/f'mobile-{label}.png'),timeout=90000)
  try:
   await page.goto(f'http://127.0.0.1:8765/{C}/qa-atelier.html?quality=efficient',wait_until='domcontentloaded');await page.wait_for_function('window.__contextQA && window.assemblyInspect && !assemblyInspect().loading && assemblyInspect().presentation.interactive',timeout=240000);print('interactive',flush=True);await page.evaluate('__contextQA.pause()')
   await page.evaluate("__contextQA.focus('crown')");await page.wait_for_function('!__contextQA.snapshot().cameraMoving',timeout=60000);await save('before-tap');point=await page.evaluate("__contextQA.target('CROWN')");assert point and not point.get('missing'),point;report['target']=point;await page.touchscreen.tap(point['x'],point['y']);await page.locator('.watch-object-actions').wait_for(state='visible');print('touch card visible',flush=True);await save('after-tap-settled');assert not report['errors'],report['errors'];report['passed']=True
  except Exception as e:report['passed']=False;report['failure']=repr(e);raise
  finally:(O/'mobile-qa-report.json').write_text(json.dumps(report,indent=2));await browser.close()
asyncio.run(main())
